      "content": "{\n  \"name\": \"aegis\",\n  \"version\": \"2.14.2\",\n  \"private\": true,\n  \"license\": \"MIT\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/GanyuanRan/Aegis.git\"\n  },\n  \"type\": \"module\",\n  \"main\": \".opencode/plugins/aegis.js\",\n  \"keywords\": [\n    \"pi-package\",\n    \"agent-skills\",\n    \"aegis\",\n    \"method-pack\",\n    \"dsh-plugin\",\n    \"deepseek-harness\"\n  ],\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./extensions/dsh/cordis.patch.yml\"\n    }\n  },\n  \"pi\": {\n    \"skills\": [\n      \"./skills\"\n    ],\n    \"extensions\": [\n      \"./extensions/pi\"\n    ]\n  },\n  \"omp\": {\n    \"extensions\": [\n      \"./extensions/omp\"\n    ]\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/dsh-agent\": \">=0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-llm\": \">=0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-skill-filesystem\": \">=0.1.0-rc.6\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/dsh-agent\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-llm\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-skill-filesystem\": {\n      \"optional\": true\n    }\n  }\n}\n"
